import { useState, useRef, useEffect, useCallback } from "react";
import "./App.css";

const LANGUAGE_CONFIG = {
  JavaScript: { icon: "⚡", ext: "js", color: "#f7df1e" },
  Python:     { icon: "🐍", ext: "py", color: "#4db6ac" },
  Java:       { icon: "☕", ext: "java", color: "#ff8a65" },
  "C++":      { icon: "⚙️", ext: "cpp", color: "#64b5f6" },
};

/* ── Toast ── */
function Toast({ message, type, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 3000);
    return () => clearTimeout(t);
  }, [onClose]);
  return <div className={`toast toast-${type}`}>{message}</div>;
}

/* ── Markdown renderer ── */
function renderMarkdown(raw) {
  if (!raw) return "";
  let html = raw
    .replace(/```[\w]*\n?([\s\S]*?)```/g,
      '<div class="md-block"><pre><code>$1</code></pre></div>')
    .replace(/^### (.+)$/gm, '<h3 class="md-h3">$1</h3>')
    .replace(/^## (.+)$/gm,  '<h2 class="md-h2">$1</h2>')
    .replace(/^# (.+)$/gm,   '<h1 class="md-h1">$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,     '<em>$1</em>')
    .replace(/`([^`]+)`/g,     '<code class="md-inline">$1</code>')
    .replace(/^---$/gm,        '<hr class="md-hr" />')
    .replace(/^\d+\.\s+(.+)$/gm,
      '<div class="md-item md-num"><span class="md-bullet">›</span><span>$1</span></div>')
    .replace(/^\*\s+(.+)$/gm,
      '<div class="md-item"><span class="md-bullet">•</span><span>$1</span></div>')
    .replace(/\n{2,}/g, '</p><p class="md-p">')
    .replace(/\n/g, '<br/>');
  return `<p class="md-p">${html}</p>`;
}

/* ── Main App ── */
export default function App() {
  const [code,     setCode]     = useState("");
  const [language, setLanguage] = useState("JavaScript");
  const [review,   setReview]   = useState("");
  const [loading,  setLoading]  = useState(false);
  const [toast,    setToast]    = useState(null);
  const textareaRef = useRef(null);

  const lines  = code.split("\n").length;
  const chars  = code.length;
  const lang   = LANGUAGE_CONFIG[language];

  const notify = (message, type = "success") => setToast({ message, type });

  /* ── Review ── */
  const reviewCode = useCallback(async () => {
    if (!code.trim()) { notify("Paste some code first.", "error"); return; }
    setLoading(true);
    setReview("");
    try {
      const res  = await fetch("http://localhost:5000/review", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code, language }),
      });
      const data = await res.json();
      setReview(data.review || data.error || "No response from server.");
      if (!data.review) notify("Review failed.", "error");
    } catch {
      setReview("⚠️ Cannot connect to backend. Make sure it is running on port 5000.");
      notify("Connection error.", "error");
    }
    setLoading(false);
  }, [code, language]);

  /* ── Helpers ── */
  const copyText = async (text, label) => {
    if (!text) return;
    await navigator.clipboard.writeText(text);
    notify(`${label} copied!`);
  };

  const clearAll = () => { setCode(""); setReview(""); notify("Cleared."); };

  const downloadReview = () => {
    if (!review) return;
    const blob = new Blob([review], { type: "text/plain" });
    const url  = URL.createObjectURL(blob);
    const a    = Object.assign(document.createElement("a"), {
      href: url,
      download: `review-${language.toLowerCase()}-${Date.now()}.txt`,
    });
    a.click();
    URL.revokeObjectURL(url);
    notify("Review downloaded!");
  };

  /* ── Tab key & Ctrl+Enter ── */
  const handleKeyDown = (e) => {
    if (e.key === "Tab") {
      e.preventDefault();
      const s = e.target.selectionStart, en = e.target.selectionEnd;
      const next = code.slice(0, s) + "  " + code.slice(en);
      setCode(next);
      requestAnimationFrame(() => {
        if (textareaRef.current) {
          textareaRef.current.selectionStart =
          textareaRef.current.selectionEnd   = s + 2;
        }
      });
    }
    if ((e.ctrlKey || e.metaKey) && e.key === "Enter") reviewCode();
  };

  return (
    <div className="app">

      {toast && (
        <Toast key={Date.now()} message={toast.message}
               type={toast.type} onClose={() => setToast(null)} />
      )}

      {/* ── Header ── */}
      <header className="hdr">
        <div className="hdr-brand">
          <span className="brand-glyph">◈</span>
          <span className="brand-name">CodeSense</span>
          <span className="brand-tag">AI</span>
        </div>
        <span className="hdr-hint">Ctrl + Enter to review</span>
      </header>

      {/* ── Panels ── */}
      <div className="workspace">

        {/* Editor */}
        <div className="panel">
          <div className="panel-chrome">
            <span className="dot dot-r" /><span className="dot dot-y" /><span className="dot dot-g" />
            <span className="panel-filename">
              {lang.icon} editor.{lang.ext}
            </span>
            <div className="chrome-actions">
              <select className="lang-pick"
                value={language} onChange={e => setLanguage(e.target.value)}>
                {Object.entries(LANGUAGE_CONFIG).map(([l, v]) => (
                  <option key={l} value={l}>{v.icon} {l}</option>
                ))}
              </select>
              <button className="cta-ghost" onClick={() => copyText(code, "Code")} title="Copy code">⎘</button>
              <button className="cta-ghost cta-red"  onClick={clearAll}            title="Clear all">✕</button>
            </div>
          </div>

          <div className="editor-wrap">
            <div className="line-nums" aria-hidden>
              {Array.from({ length: lines }, (_, i) => <span key={i}>{i + 1}</span>)}
            </div>
            <textarea
              ref={textareaRef}
              className="code-area"
              spellCheck={false}
              placeholder={`// Paste your ${language} code here…\n// Ctrl+Enter to review`}
              value={code}
              onChange={e => setCode(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>

          <div className="editor-bar">
            <span className="stat">{lines} ln</span>
            <span className="stat">{chars} ch</span>
            <span className="stat" style={{ color: lang.color }}>{lang.icon} {language}</span>
          </div>
        </div>

        {/* Review */}
        <div className="panel panel-review-pane">
          <div className="panel-chrome">
            <span className="dot dot-r" /><span className="dot dot-y" /><span className="dot dot-g" />
            <span className="panel-filename">◈ ai-review.md</span>
            {review && (
              <div className="chrome-actions">
                <button className="cta-ghost" onClick={() => copyText(review, "Review")} title="Copy review">⎘</button>
                <button className="cta-ghost" onClick={downloadReview}                   title="Download">↓</button>
              </div>
            )}
          </div>

          <div className="review-body">
            {loading ? (
              <div className="state-loading">
                <div className="scanner"><div className="scan-beam" /></div>
                <p className="loading-label">
                  Analyzing code<span className="ellipsis"><i>.</i><i>.</i><i>.</i></span>
                </p>
                <p className="loading-sub">Running AI review · {language}</p>
              </div>
            ) : review ? (
              <div className="md-root"
                dangerouslySetInnerHTML={{ __html: renderMarkdown(review) }} />
            ) : (
              <div className="state-empty">
                <div className="empty-glyph">◈</div>
                <p>AI review appears here</p>
                <span>Paste code → click Review Code</span>
              </div>
            )}
          </div>
        </div>

      </div>

      {/* ── Action bar ── */}
      <div className="action-bar">
        <button
          className={`review-btn ${loading ? "is-loading" : ""}`}
          onClick={reviewCode}
          disabled={loading}
        >
          {loading
            ? <><span className="spin" />Reviewing…</>
            : <><span className="btn-arrow">▶</span>Review Code</>}
        </button>
      </div>

    </div>
  );
}
